    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LC1RB_0RC1LD_0RB1LA : list Instr := [].
Definition tmw_1RB0LC_1LC1RB_0RC1LD_0RB1LA : TM := tm_wrap_trs tmm_1RB0LC_1LC1RB_0RC1LD_0RB1LA pins_1RB0LC_1LC1RB_0RC1LD_0RB1LA.
Local Notation tm := tmw_1RB0LC_1LC1RB_0RC1LD_0RB1LA.

Lemma mirror_ok_1RB0LC_1LC1RB_0RC1LD_0RB1LA : mirror_tm tm_1RB0LC_1LC1RB_0RC1LD_0RB1LA = tmm_1RB0LC_1LC1RB_0RC1LD_0RB1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_1LC1RB_0RC1LD_0RB1LA (p : positive) : cconf := (StB, (Ap_Alph_110_111_111 p ++ [S0], S0, [S1])).
