Definition chi_1RB0LC_1LC1RB_0RC1LD_0RB1LA : list lstep := [SWin 1; SWinR 3; SCycL 3 0; SWin 6; SCycR 3; SWin 4].

Lemma run_int_1RB0LC_1LC1RB_0RC1LD_0RB1LA : srun tm false true chi_1RB0LC_1LC1RB_0RC1LD_0RB1LA A0_1RB0LC_1LC1RB_0RC1LD_0RB1LA = Some (A1_1RB0LC_1LC1RB_0RC1LD_0RB1LA, 6, 14).
