Definition B0_1RB0LC_1LC1RB_0RC1LD_0RB1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_1RB0LC_1LC1RB_0RC1LD_0RB1LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 1 [S1;S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
