(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC1RB_0RC1LD_0RB1LA : forall j, lift (cden [] [] j BB1_1RB0LC_1LC1RB_0RC1LD_0RB1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC1RB_0RC1LD_0RB1LA = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, [S1;S1;S1]))).
  { unfold cden, BB1_1RB0LC_1LC1RB_0RC1LD_0RB1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, [S1;S1;S1]))).
  { unfold Cin_1RB0LC_1LC1RB_0RC1LD_0RB1LA. rewrite epow2_1RB0LC_1LC1RB_0RC1LD_0RB1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1LC1RB_0RC1LD_0RB1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_1LC1RB_0RC1LD_0RB1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB0LC_1LC1RB_0RC1LD_0RB1LA.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_1LC1RB_0RC1LD_0RB1LA, cden, BM0_1RB0LC_1LC1RB_0RC1LD_0RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

