(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1LC1RB_0RD1LA_0RB___ : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LC_1LC1RB_0RD1LA_0RB___.
