Lemma gsi_1RB0LC_1LC1RD_0RB1LA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LC_1LC1RD_0RB1LA_1LC1RB.
