(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_1LC1RD_0RD1LC_1LC1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB0LC_1LC1RD_0RD1LC_1LC1RA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 6), (cden [] [] j BB1_1RB0LC_1LC1RD_0RD1LC_1LC1RA).
      split; [lia|]. split; [| exact (gbo_1RB0LC_1LC1RD_0RD1LC_1LC1RA j)].
      rewrite (gso_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j E).
      exact (srun_sound tm true true chb_1RB0LC_1LC1RD_0RD1LC_1LC1RA B0_1RB0LC_1LC1RD_0RD1LC_1LC1RA BB1_1RB0LC_1LC1RD_0RD1LC_1LC1RA 6 6
               run_boot_1RB0LC_1LC1RD_0RD1LC_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LC_1LC1RD_0RD1LC_1LC1RA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 4), (cden [] [] j BM1_1RB0LC_1LC1RD_0RD1LC_1LC1RA).
      split; [| exact (gbo2_1RB0LC_1LC1RD_0RD1LC_1LC1RA j)].
      rewrite (gxi_1RB0LC_1LC1RD_0RD1LC_1LC1RA j).
      exact (srun_sound tm true true chm_1RB0LC_1LC1RD_0RD1LC_1LC1RA BM0_1RB0LC_1LC1RD_0RD1LC_1LC1RA BM1_1RB0LC_1LC1RD_0RD1LC_1LC1RA 6 4
               run_shift_1RB0LC_1LC1RD_0RD1LC_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (6 * j + 8), (cden [] [] j B1_1RB0LC_1LC1RD_0RD1LC_1LC1RA).
    split; [| exact (geo_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j E)].
    rewrite (gxi2_1RB0LC_1LC1RD_0RD1LC_1LC1RA j).
    exact (srun_sound tm true true che_1RB0LC_1LC1RD_0RD1LC_1LC1RA BE0_1RB0LC_1LC1RD_0RD1LC_1LC1RA B1_1RB0LC_1LC1RD_0RD1LC_1LC1RA 6 8
             run_exit_1RB0LC_1LC1RD_0RD1LC_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
