(** ** The lap *)

Lemma lap_1RB0LC_1LC1RD_0RD1LC_1LC1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1LC1RD_0RD1LC_1LC1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LC1RD_0RD1LC_1LC1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB0LC_1LC1RD_0RD1LC_1LC1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LC_1LC1RD_0RD1LC_1LC1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 6), (cden [] [] j BB1_1RB0LC_1LC1RD_0RD1LC_1LC1RA).
    split; [lia|]. split; [| exact (gbo_1RB0LC_1LC1RD_0RD1LC_1LC1RA j)].
    rewrite (gso_1RB0LC_1LC1RD_0RD1LC_1LC1RA p j E).
    exact (srun_sound tm true true chb_1RB0LC_1LC1RD_0RD1LC_1LC1RA B0_1RB0LC_1LC1RD_0RD1LC_1LC1RA BB1_1RB0LC_1LC1RD_0RD1LC_1LC1RA 6 6
             run_boot_1RB0LC_1LC1RD_0RD1LC_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LC_1LC1RD_0RD1LC_1LC1RA p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_1RB0LC_1LC1RD_0RD1LC_1LC1RA).
    split; [| exact (gbo2_1RB0LC_1LC1RD_0RD1LC_1LC1RA j)].
    rewrite (gxi_1RB0LC_1LC1RD_0RD1LC_1LC1RA j).
    exact (srun_sound tm true true chm_1RB0LC_1LC1RD_0RD1LC_1LC1RA BM0_1RB0LC_1LC1RD_0RD1LC_1LC1RA BM1_1RB0LC_1LC1RD_0RD1LC_1LC1RA 6 4
             run_shift_1RB0LC_1LC1RD_0RD1LC_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB0LC_1LC1RD_0RD1LC_1LC1RA t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB0LC_1LC1RD_0RD1LC_1LC1RA xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB0LC_1LC1RD_0RD1LC_1LC1RA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC1RD_0RD1LC_1LC1RA : forall t, ~ In t pins_1RB0LC_1LC1RD_0RD1LC_1LC1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC1RD_0RD1LC_1LC1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 5; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_1LC1RD_0RD1LC_1LC1RA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_1LC1RD_0RD1LC_1LC1RA [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LC_1LC1RD_0RD1LC_1LC1RA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LC_1LC1RD_0RD1LC_1LC1RA : NeverQuasiHaltsTr tmm_1RB0LC_1LC1RD_0RD1LC_1LC1RA.
Proof.
  apply (glue_neverqhtr tmm_1RB0LC_1LC1RD_0RD1LC_1LC1RA pins_1RB0LC_1LC1RD_0RD1LC_1LC1RA Cc 1).
  - exact boot_1RB0LC_1LC1RD_0RD1LC_1LC1RA.
  - intros p _. apply lap_1RB0LC_1LC1RD_0RD1LC_1LC1RA.
  - intros t Ht p _. apply fire_1RB0LC_1LC1RD_0RD1LC_1LC1RA. exact Ht.
Qed.

Theorem nqhtr_1RB0LC_1LC1RD_0RD1LC_1LC1RA : NeverQuasiHaltsTr tm_1RB0LC_1LC1RD_0RD1LC_1LC1RA.
Proof. apply (neverqhtr_mirror tm_1RB0LC_1LC1RD_0RD1LC_1LC1RA). rewrite mirror_ok_1RB0LC_1LC1RD_0RD1LC_1LC1RA. exact nqhtrm_1RB0LC_1LC1RD_0RD1LC_1LC1RA. Qed.

