Lemma gsi_1RB0LC_1LC1RD_0RD1LC_1RA1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_111_101_1 q0 ++ [S1;S1;S0]) [] j A0_1RB0LC_1LC1RD_0RD1LC_1RA1RA.
