Definition tmm_1RB0LC_1LC1RD_0RD1LC_1RB1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1LC1RD_0RD1LC_1RB1RA : list Instr := [].
Definition tmw_1RB0LC_1LC1RD_0RD1LC_1RB1RA : TM := tm_wrap_trs tmm_1RB0LC_1LC1RD_0RD1LC_1RB1RA pins_1RB0LC_1LC1RD_0RD1LC_1RB1RA.
