Lemma mirror_ok_1RB0LC_1LC1RD_0RD1LC_1RB1RA : mirror_tm tm_1RB0LC_1LC1RD_0RD1LC_1RB1RA = tmm_1RB0LC_1LC1RD_0RD1LC_1RB1RA.
