(** The chain into this family lands on its anchor up to 2/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1LC1RD_0RD1LC_1RB1RA : forall j, lift (cden [] [] j BB1_1RB0LC_1LC1RD_0RD1LC_1RB1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1LC1RD_0RD1LC_1RB1RA = (StC, (((rep [S1;S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0LC_1LC1RD_0RD1LC_1RB1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB0LC_1LC1RD_0RD1LC_1RB1RA. rewrite epow2_1RB0LC_1LC1RD_0RD1LC_1RB1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1LC1RD_0RD1LC_1RB1RA. rewrite ?lift_app_blank. reflexivity.
