Definition tmm_1RB0LC_1RC0RA_1LD0LC_0RB1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1RC0RA_1LD0LC_0RB1LC : list Instr := [].
Definition tmw_1RB0LC_1RC0RA_1LD0LC_0RB1LC : TM := tm_wrap_trs tmm_1RB0LC_1RC0RA_1LD0LC_0RB1LC pins_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
Local Notation tm := tmw_1RB0LC_1RC0RA_1LD0LC_0RB1LC.

Lemma mirror_ok_1RB0LC_1RC0RA_1LD0LC_0RB1LC : mirror_tm tm_1RB0LC_1RC0RA_1LD0LC_0RB1LC = tmm_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_1RC0RA_1LD0LC_0RB1LC (p : positive) : cconf := (StD, (Jp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB0LC_1RC0RA_1LD0LC_0RB1LC.

(** ** The certificate *)

Definition A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB0LC_1RC0RA_1LD0LC_0RB1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_1RB0LC_1RC0RA_1LD0LC_0RB1LC : srun tm false true chi_1RB0LC_1RC0RA_1LD0LC_0RB1LC A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Some (A1_1RB0LC_1RC0RA_1LD0LC_0RB1LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S1] 1 1 [S1;S0]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StD *)
Definition Cin_1RB0LC_1RC0RA_1LD0LC_0RB1LC (v : positive) : cconf := (StD, (Jp v ++ [S0;S1;S1], S0, [])).
Local Notation Cin := Cin_1RB0LC_1RC0RA_1LD0LC_0RB1LC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB0LC_1RC0RA_1LD0LC_0RB1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_1RB0LC_1RC0RA_1LD0LC_0RB1LC : srun tm false true chn_1RB0LC_1RC0RA_1LD0LC_0RB1LC AI0_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Some (AI1_1RB0LC_1RC0RA_1LD0LC_0RB1LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB0LC_1RC0RA_1LD0LC_0RB1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_1RB0LC_1RC0RA_1LD0LC_0RB1LC : srun tm true true chb_1RB0LC_1RC0RA_1LD0LC_0RB1LC B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Some (BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LC_1RC0RA_1LD0LC_0RB1LC : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB0LC_1RC0RA_1LD0LC_0RB1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB0LC_1RC0RA_1LD0LC_0RB1LC : srun tm true true che_1RB0LC_1RC0RA_1LD0LC_0RB1LC BE0_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Some (B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0LC_1RC0RA_1LD0LC_0RB1LC, cden, A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S0]) [] j A1_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB0LC_1RC0RA_1LD0LC_0RB1LC, cden, A1_1RB0LC_1RC0RA_1LD0LC_0RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LC_1RC0RA_1LD0LC_0RB1LC A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC A1_1RB0LC_1RC0RA_1LD0LC_0RB1LC 4 4
             run_int_1RB0LC_1RC0RA_1LD0LC_0RB1LC (Jp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j q0 E).
Qed.

Lemma gso_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB0LC_1RC0RA_1LD0LC_0RB1LC, cden, B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC
             = (StD, (rep [S1;S1] (S j) ++ [S1;S0], S0, []))).
  { unfold cden, B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, (rep [S1;S1] (S j) ++ [S1;S0], S0, []))).
  { unfold Cc_1RB0LC_1RC0RA_1LD0LC_0RB1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. reflexivity.
Qed.

Lemma gsn_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ [S0;S1;S1]) [] i AI0_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_1RB0LC_1RC0RA_1LD0LC_0RB1LC, cden, AI0_1RB0LC_1RC0RA_1LD0LC_0RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ [S0;S1;S1]) [] i AI1_1RB0LC_1RC0RA_1LD0LC_0RB1LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (_ & H2).
  unfold Cin_1RB0LC_1RC0RA_1LD0LC_0RB1LC, cden, AI1_1RB0LC_1RC0RA_1LD0LC_0RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Jp q0 ++ [S0;S1;S1]) [] i AI1_1RB0LC_1RC0RA_1LD0LC_0RB1LC).
  split; [lia|]. split; [| exact (gen_1RB0LC_1RC0RA_1LD0LC_0RB1LC v i q0 E)].
  rewrite (gsn_1RB0LC_1RC0RA_1LD0LC_0RB1LC v i q0 E).
  exact (srun_sound tm false true chn_1RB0LC_1RC0RA_1LD0LC_0RB1LC AI0_1RB0LC_1RC0RA_1LD0LC_0RB1LC AI1_1RB0LC_1RC0RA_1LD0LC_0RB1LC 4 4
           run_inner_1RB0LC_1RC0RA_1LD0LC_0RB1LC (Jp q0 ++ [S0;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall j, lift (cden [] [] j BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC = (StD, (rep [S1;S1] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S1] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_1RB0LC_1RC0RA_1LD0LC_0RB1LC. rewrite epow2_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1RC0RA_1LD0LC_0RB1LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_1RC0RA_1LD0LC_0RB1LC, cden, BE0_1RB0LC_1RC0RA_1LD0LC_0RB1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_1RC0RA_1LD0LC_0RB1LC p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC).
    split; [lia|]. split; [| exact (gbo_1RB0LC_1RC0RA_1LD0LC_0RB1LC j)].
    rewrite (gso_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j E).
    exact (srun_sound tm true true chb_1RB0LC_1RC0RA_1LD0LC_0RB1LC B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC BB1_1RB0LC_1RC0RA_1LD0LC_0RB1LC 4 8
             run_boot_1RB0LC_1RC0RA_1LD0LC_0RB1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 8), (cden [] [] j B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC).
    split; [| exact (geo_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j E)].
    rewrite (gxi_1RB0LC_1RC0RA_1LD0LC_0RB1LC j).
    exact (srun_sound tm true true che_1RB0LC_1RC0RA_1LD0LC_0RB1LC BE0_1RB0LC_1RC0RA_1LD0LC_0RB1LC B1_1RB0LC_1RC0RA_1LD0LC_0RB1LC 4 8
             run_exit_1RB0LC_1RC0RA_1LD0LC_0RB1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_1RC0RA_1LD0LC_0RB1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j (Jp q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LC_1RC0RA_1LD0LC_0RB1LC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1RC0RA_1LD0LC_0RB1LC : forall t, ~ In t pins_1RB0LC_1RC0RA_1LD0LC_0RB1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1RC0RA_1LD0LC_0RB1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LC_1RC0RA_1LD0LC_0RB1LC
