Lemma lbl_1RB0LC_1RC0RA_1LD1LC_0RB0LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LC_1RC0RA_1LD1LC_0RB0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1RC0RA_1LD1LC_0RB0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LC_1RC0RA_1LD1LC_0RB0LD
             = (StD, (rep [S1;S1] (S j) ++ [S1;S1], S0, []))).
