Lemma gsn_1RB0LC_1RC0RA_1LD1LC_0RB0LD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_1RB0LC_1RC0RA_1LD1LC_0RB0LD.
Proof.
