(** ** Bootstrap *)

Lemma boot_1RB0LC_1RC0RA_1LD1LC_0RB0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
