  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1RC0RA_1LD1LC_0RB0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1RC0RA_1LD1LC_0RB0LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LC_1RC0RA_1LD1LC_0RB0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LC_1RC0RA_1LD1LC_0RB0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_1RC0RA_1LD1LC_0RB0LD t p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_1RB0LC_1RC0RA_1LD1LC_0RB0LD). split;
      [| exact (gbo_1RB0LC_1RC0RA_1LD1LC_0RB0LD j)].
