    exact (srun_sound tm true true chb_1RB0LC_1RC0RA_1LD1LC_0RB0LD B0_1RB0LC_1RC0RA_1LD1LC_0RB0LD BB1_1RB0LC_1RC0RA_1LD1LC_0RB0LD 8 4
             run_boot_1RB0LC_1RC0RA_1LD1LC_0RB0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
