(** ** The lap *)

Lemma lap_1RB0LC_1RC0RA_1LD1LC_0RB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
