    intros p1 j1 E1.
    exact (firex_1RB0LC_1RC1RA_0LA1LD_0RB1LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LC_1RC1RA_0LA1LD_0RB1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_1RC1RA_0LA1LD_0RB1LC (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_1RC1RA_0LA1LD_0RB1LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
