(** ** The lap *)

Lemma lap_1RB0LC_1RC1RA_0RD1LC_1LD1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
