Lemma fireo_1RB0LC_1RC1RA_0RD1LC_1LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1RC1RA_0RD1LC_1LD1RB = Some t ->
