  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_1RC1RA_0RD1LC_1LD1RB t p (pow2 j)).
  - exists (4 * j + 16), (cden [] [] j BB1_1RB0LC_1RC1RA_0RD1LC_1LD1RB). split;
      [| exact (gbo_1RB0LC_1RC1RA_0RD1LC_1LD1RB j)].
