Lemma mirror_ok_1RB0LC_1RC1RA_1LB1LD_0RB1LD : mirror_tm tm_1RB0LC_1RC1RA_1LB1LD_0RB1LD = tmm_1RB0LC_1RC1RA_1LB1LD_0RB1LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LC_1RC1RA_1LB1LD_0RB1LD (p : positive) : cconf := (StD, (Jp p ++ [S0], S0, [])).
