Lemma gz_1RB0LC_1RC1RA_1LC1LD_0RB1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] 0 Z0_1RB0LC_1RC1RA_1LC1LD_0RB1LD /\
