    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_1RC1RD_0RD1LC_1LB1RA : list Instr := [].
Definition tmw_1RB0LC_1RC1RD_0RD1LC_1LB1RA : TM := tm_wrap_trs tmm_1RB0LC_1RC1RD_0RD1LC_1LB1RA pins_1RB0LC_1RC1RD_0RD1LC_1LB1RA.
Local Notation tm := tmw_1RB0LC_1RC1RD_0RD1LC_1LB1RA.

Lemma mirror_ok_1RB0LC_1RC1RD_0RD1LC_1LB1RA : mirror_tm tm_1RB0LC_1RC1RD_0RD1LC_1LB1RA = tmm_1RB0LC_1RC1RD_0RD1LC_1LB1RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

