(** The chain into this family lands on its anchor up to 2/0
    trailing blanks. *)
Lemma gbo_1RB0LC_1RC1RD_0RD1LC_1LB1RA : forall j, lift (cden [] [] j BB1_1RB0LC_1RC1RD_0RD1LC_1LB1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LC_1RC1RD_0RD1LC_1LB1RA = (StC, (((rep [S1;S1;S1] j ++ [S1;S1;S1;S1]) ++ [S0]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0LC_1RC1RD_0RD1LC_1LB1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S1;S1] j ++ [S1;S1;S1;S1], S0, []))).
  { unfold Cin_1RB0LC_1RC1RD_0RD1LC_1LB1RA. rewrite epow2_1RB0LC_1RC1RD_0RD1LC_1LB1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LC_1RC1RD_0RD1LC_1LB1RA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LC_1RC1RD_0RD1LC_1LB1RA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB0LC_1RC1RD_0RD1LC_1LB1RA.
Proof.
  intro j.
  destruct (Alph_111_101_1.cview_none_Alph_111_101_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LC_1RC1RD_0RD1LC_1LB1RA, cden, BM0_1RB0LC_1RC1RD_0RD1LC_1LB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

