(** ** The lap *)

Lemma lap_1RB0LD_0LB1RC_1LA1RA_0RC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
