  - destruct (lapi_1RB0LD_0LB1RC_1LA1RA_0RC1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_0LB1RC_1LA1RA_0RC1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_0LB1RC_1LA1RA_0RC1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 70.
  assert (H : match csteps tm 70 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 70 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_0LB1RC_1LA1RA_0RC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_0LB1RC_1LA1RA_0RC1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_0LB1RC_1LA1RA_0RC1LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB0LD_0LB1RC_1LA1RA_0RC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LD_0LB1RC_1LA1RA_0RC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 8), (cden [] [] j BB1_1RB0LD_0LB1RC_1LA1RA_0RC1LD).
    split; [lia|]. split; [| exact (gbo_1RB0LD_0LB1RC_1LA1RA_0RC1LD j)].
    rewrite (gso_1RB0LD_0LB1RC_1LA1RA_0RC1LD p j E).
    exact (srun_sound tm true true chb_1RB0LD_0LB1RC_1LA1RA_0RC1LD B0_1RB0LD_0LB1RC_1LA1RA_0RC1LD BB1_1RB0LD_0LB1RC_1LA1RA_0RC1LD 6 8
             run_boot_1RB0LD_0LB1RC_1LA1RA_0RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LD_0LB1RC_1LA1RA_0RC1LD p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_1RB0LD_0LB1RC_1LA1RA_0RC1LD).
    split; [| exact (gbo2_1RB0LD_0LB1RC_1LA1RA_0RC1LD j)].
    rewrite (gxi_1RB0LD_0LB1RC_1LA1RA_0RC1LD j).
    exact (srun_sound tm true true chm_1RB0LD_0LB1RC_1LA1RA_0RC1LD BM0_1RB0LD_0LB1RC_1LA1RA_0RC1LD BM1_1RB0LD_0LB1RC_1LA1RA_0RC1LD 6 4
             run_shift_1RB0LD_0LB1RC_1LA1RA_0RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin3 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB0LD_0LB1RC_1LA1RA_0RC1LD p (pow2 j) (pow2 j));
      [exact HB2|].
    exists (6 * j + 8), (cden [] [] j BM31_1RB0LD_0LB1RC_1LA1RA_0RC1LD).
    split; [| exact (gbo3_1RB0LD_0LB1RC_1LA1RA_0RC1LD j)].
    rewrite (gxi2_1RB0LD_0LB1RC_1LA1RA_0RC1LD j).
    exact (srun_sound tm true true chm3_1RB0LD_0LB1RC_1LA1RA_0RC1LD BM30_1RB0LD_0LB1RC_1LA1RA_0RC1LD BM31_1RB0LD_0LB1RC_1LA1RA_0RC1LD 6 8
             run_shift3_1RB0LD_0LB1RC_1LA1RA_0RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
