    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin3 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin3 (fill (pow2 j)))
                    true true l BE0_1RB0LD_0LB1RC_1LA1RA_0RC1LD xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi3_1RB0LD_0LB1RC_1LA1RA_0RC1LD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_0LB1RC_1LA1RA_0RC1LD : forall t, ~ In t pins_1RB0LD_0LB1RC_1LA1RA_0RC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_0LB1RC_1LA1RA_0RC1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0LB1RC_1LA1RA_0RC1LD (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0LB1RC_1LA1RA_0RC1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_0LB1RC_1LA1RA_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 5]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LD_0LB1RC_1LA1RA_0RC1LD : NeverQuasiHaltsTr tmm_1RB0LD_0LB1RC_1LA1RA_0RC1LD.
Proof.
  apply (glue_neverqhtr tmm_1RB0LD_0LB1RC_1LA1RA_0RC1LD pins_1RB0LD_0LB1RC_1LA1RA_0RC1LD Cc 2).
