    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LD_0LB1RC_1LD1RA_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 5; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
