Lemma gsi_1RB0LD_0LC0RD_1LA1LC_0RB1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j A0_1RB0LD_0LC0RD_1LA1LC_0RB1RB.
