    apply (lap_of_run tm Cc true true cho_1RB0LD_0LC0RD_1LA1LC_0RB1RB B0_1RB0LD_0LC0RD_1LA1LC_0RB1RB B1_1RB0LD_0LC0RD_1LA1LC_0RB1RB 6 12 p j' [] []).
    + exact run_ovf_1RB0LD_0LC0RD_1LA1LC_0RB1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_0LC0RD_1LA1LC_0RB1RB p j' E).
    + exact (geo_1RB0LD_0LC0RD_1LA1LC_0RB1RB p j' E).
    + lia.
