Lemma geo_1RB0LD_0LC0RD_1RD1LC_0LA1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_0LC0RD_1RD1LC_0LA1RA) = lift (Cc (Pos.succ p)).
