(** ** The lap *)

Lemma lap_1RB0LD_0LC0RD_1RD1LC_0LA1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
