    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0LC0RD_1RD1LC_0LA1RA [SWinR 2; SRotL 1; SWin 1; SCycL 3 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB0LD_0LC0RD_1RD1LC_0LA1RA : NeverQuasiHaltsTr tm_1RB0LD_0LC0RD_1RD1LC_0LA1RA.
Proof.
