  unfold Cin_1RB0LD_0LC0RD_1RD1LC_0LC1RA, cden, AI0_1RB0LD_0LC0RD_1RD1LC_0LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LD_0LC0RD_1RD1LC_0LC1RA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_1RB0LD_0LC0RD_1RD1LC_0LC1RA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_1RB0LD_0LC0RD_1RD1LC_0LC1RA, cden, AI1_1RB0LD_0LC0RD_1RD1LC_0LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
