Lemma geo_1RB0LD_0LC0RD_1RD1LC_0LD1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_0LC0RD_1RD1LC_0LD1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LD_0LC0RD_1RD1LC_0LD1RA
             = (StA, (rep [S1;S0;S1] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB0LD_0LC0RD_1RD1LC_0LD1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
