Definition tm_1RB0LD_0LC1RA_1LA1LC_0RA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DL StC
