    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0LC1RA_1LA1LC_0RA1LD [SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0LC1RA_1LA1LC_0RA1LD (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0LC1RA_1LA1LC_0RA1LD [SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0LC1RA_1LA1LC_0RA1LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0LC1RA_1LA1LC_0RA1LD [SCycL 2 0; SWin 1; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
