(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_0LC1RA_1LA1LC_0RB0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_0LC1RA_1LA1LC_0RB0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_0LC1RA_1LA1LC_0RB0RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_0LC1RA_1LA1LC_0RB0RA p j E)].
Qed.


